  vi.stubGlobal('localStorage', { getItem: () => { throw new Error('Denied'); }, setItem: () => { throw new Error('Full'); } });
  expect(readSize()).toBe(4);
  expect(readBests()).toEqual({});
  expect(() => saveSize(6)).not.toThrow();
  expect(saveBest({}, 4, 8)).toEqual({ 4: 8 });
});

